"""Generate the assertion-level archive register from explicit reviewed records."""
from pathlib import Path
import csv

ROOT = Path(__file__).parent
rows = []
def add(cote, scan, assertion, status, result, proof='', kind='supplied transcription'):
    rows.append(dict(question_id=f'A-Q{len(rows)+1:03}', cote=cote, scan=scan,
                     source_kind=kind,
                     source_file=f'ARCHIVE_{cote}_scan{int(scan):03}.tex' if kind=='supplied transcription' else 'SA17_STUDY_cote133_lambda.md',
                     assertion=assertion, status=status, result_or_exact_gate=result,
                     proof_id=proof, scan_verification='Not yet visually checked against original; public access attempt recorded separately'))

